"use strict";(globalThis.webpackChunkwebsite=globalThis.webpackChunkwebsite||[]).push([[82655],{30698:e=>{e.exports=JSON.parse('{"tag":{"label":"consentless analytics","permalink":"/tags/consentless-analytics","allTagsPath":"/tags","count":14,"items":[{"id":"security-privacy/consentless-benefits","title":"Benefits of Consentless Tracking","description":"What you gain by measuring without consent \u2014 no data lost to banner rejection, far less for ad blockers to strip, no CMP to maintain, and cleaner attribution.","permalink":"/security-privacy/consentless-benefits"},{"id":"guides/complete-guide-cookieless-analytics","title":"Complete Guide to Cookieless Analytics 2026","description":"Cookieless analytics measures visitors without consent banners: how it works, why cookie-based tools lose 15-60% of EU data, and how to set it up.","permalink":"/guides/complete-guide-cookieless-analytics"},{"id":"faq/consentless-analytics","title":"Consentless Analytics","description":"Why, on our self-assessment, Sealmetrics needs no consent banner for its own analytics (Germany is an open question) \u2014 no cookies, nothing stored on the device, a session identifier that rotates daily, and what exactly is recorded on each hit.","permalink":"/faq/consentless-analytics"},{"id":"faq/privacy-security","title":"Frequently Asked Questions","description":"Why Sealmetrics numbers differ from GA4 \u2014 inflated Direct traffic, entrances instead of persistent-ID sessions, last-click as the only consent-free attribution model, ITP resistance, and why server-side tracking still needs a consent banner.","permalink":"/faq/privacy-security"},{"id":"faq/index","title":"Frequently Asked Questions (FAQ)","description":"Answers to the most common questions about Sealmetrics, consentless analytics, attribution, implementation, privacy, product features, and legal compliance.","permalink":"/faq/"},{"id":"security-privacy/how-consentless-works","title":"How Consentless Tracking Works","description":"The mechanics of consentless tracking \u2014 a small set of non-identifying fields, isolated hits, a daily re-keyed session identifier, and EU-only aggregate storage.","permalink":"/security-privacy/how-consentless-works"},{"id":"compliance/omnibus/impact-analytics","title":"Impact on Web Analytics and Tracking","description":"How the Digital Omnibus affects web analytics, consent requirements, and consentless tracking solutions","permalink":"/compliance/omnibus/impact-analytics"},{"id":"index","title":"Sealmetrics Docs \u2014 Consentless Web Analytics","description":"Official documentation for Sealmetrics, the consentless web analytics platform that measures traffic without cookies and, by its own assessment, without consent banners, storing nothing that identifies anyone.","permalink":"/"},{"id":"compare/google-analytics-4","title":"Sealmetrics vs Google Analytics 4: consent-based vs consentless measurement","description":"GA4 needs cookies and consent, so it loses 15\u201360% of EU visitors. Sealmetrics measures without cookies or IP storage, hosted in Dublin; no banner, by our self-assessment.","permalink":"/compare/google-analytics-4"},{"id":"compare/matomo","title":"Sealmetrics vs Matomo: self-hosted open source vs managed consentless cloud","description":"Matomo is GPL-licensed and self-hostable, but its cookieless mode hashes the visitor\'s IP. Sealmetrics doesn\'t store the IP or build its identifier from it, and keeps analytics data in Dublin.","permalink":"/compare/matomo"},{"id":"security-privacy/index","title":"Security & Privacy","description":"How Sealmetrics measures without identifying anyone \u2014 a small set of non-identifying fields, nothing stored on the device, EU-only storage in Dublin \u2014 with the index of every privacy and security page.","permalink":"/security-privacy/"},{"id":"security-privacy/consentless-analytics","title":"What is Consentless Analytics?","description":"What consentless analytics is, the small set of non-identifying fields Sealmetrics records, and why storing nothing on the device and nothing that identifies anyone means, on our self-assessment, no consent banner is required (in Germany an open question).","permalink":"/security-privacy/consentless-analytics"},{"id":"security-privacy/what-we-track","title":"What We Track vs What We Don\u2019t","description":"Field-by-field list of what Sealmetrics records on every hit, how long each field is kept, and what it never collects.","permalink":"/security-privacy/what-we-track"},{"id":"security-privacy/why-no-consent","title":"Why Sealmetrics Can Measure Without Consent","description":"Sealmetrics needs no consent banner because it stores nothing on the visitor\'s device and no data that identifies anyone, and fits the audience-measurement exemption \u2014 the short version, as our self-assessment.","permalink":"/security-privacy/why-no-consent"}],"unlisted":false}}')}}]);